Here is a simple HTML/CSS/JavaScript example to create a bouncing "DVD Logo" (represented by text).

This code uses basic CSS for styling and JavaScript to handle the movement, collision detection, and bouncing effect without gravity.

```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Bouncing DVD Logo</title>
    <style>
        body {
            margin: 0;
            overflow: hidden; /* Prevents scrollbars from appearing due to movement */
            background-color: #f0f0f0;
            height: 100vh;
        }

        #dvdLogo {
            position: absolute;
            font-size: 60px;
            padding: 10px;
            /* Placeholder text for the DVD logo */
            content: "DVD"; 
            user-select: none; /* Prevents text selection during movement */
        }
    </style>
</head>
<body>

    <div id="dvdLogo">DVD</div>

    <script>
        const dvdLogo = document.getElementById('dvdLogo');
        const containerWidth = window.innerWidth;
        const containerHeight = window.innerHeight;

        // Initial state
        let x = 50;
        let y = 50;
        let dx = 4; // Velocity in X direction (speed)
        let dy = 3; // Velocity in Y direction (speed)

        // Update the logo's position on the screen
        function updatePosition() {
            // 1. Move the object
            x += dx;
            y += dy;

            // 2. Collision Detection (Walls)

            // Check horizontal boundaries
            if (x + dvdLogo.offsetWidth > containerWidth || x - dvdLogo.offsetWidth < 0) {
                dx = -dx; // Reverse X direction
            }

            // Check vertical boundaries
            if (y + dvdLogo.offsetHeight > containerHeight || y - dvdLogo.offsetHeight < 0) {
                dy = -dy; // Reverse Y direction
            }

            // 3. Apply new position to the element
            dvdLogo.style.left = `${x}px`;
            dvdLogo.style.top = `${y}px`;

            // Request the next frame for smooth animation (no gravity simulation)
            requestAnimationFrame(updatePosition);
        }

        // Set initial position and start the loop
        dvdLogo.style.left = `${x}px`;
        dvdLogo.style.top = `${y}px`;

        // Start the animation loop
        window.onload = function() {
            updatePosition();
        };

    </script>
</body>
</html>
```
